	private static int maxAbsPcm16(byte[] pcm)
	{
		int max = 0;
		for (int index = 0; index + 1 < pcm.length; index += 2)
		{
			int low = pcm[index] & 0xff;
			int high = pcm[index + 1];
			int value = (high << 8) | low;
			max = Math.max(max, Math.abs(value));
		}
		return max;
	}

