	private boolean inactivePanelAimBoxAtCached(int x, int y)
	{
		for (InventoryAimBox box : inventoryBoxes)
		{
			if (isDrawable(box.hiddenUntilNanos)
				&& contains(box.lastBounds, x, y)
				&& box.activeBounds == null)
